export type FieldType = "text" | "number" | "date" | "select";

export interface CustomField {
  id: string;
  label: string;
  type: FieldType;
  options: string[];
}

export interface CustomModule {
  id: string;
  name: string;
  icon: string;
  color: string;
  description: string | null;
  fields: CustomField[];
  created_at: string;
}

export interface CustomEntry {
  id: string;
  module_id: string;
  data: Record<string, string | number>;
  created_at: string;
}

